  const c1 = colOrder(x.col), c2 = colOrder(y.col)
  const out = []
  for (let c = Math.min(c1, c2); c <= Math.max(c1, c2); c++) {
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: colFromOrder(c), row: r })
  }
  return out
}

// ---- evaluation
const memo = new Map()
const INPROG = {}
function cellValue(col, row) {
  const key = col + row
  const cell = cells.get(key)
  if (!cell) return num(0)
  if (memo.has(key)) {
    const m = memo.get(key)
    return m === INPROG ? err('#CYCLE!') : m
  }
  memo.set(key, INPROG)
  const v = evalCell(cell)
  memo.set(key, v)
  return v
}
function evalCell(cell) {
  const c = cell.content
  if (c[0] === '=') {
    const ast = getAst(cell)
    if (!ast) return err('#ERR!')
    return ev(ast)
  }
  if (c === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
  if (ERRS.includes(c)) return err(c)
  return { k: 's', v: c }
}

function toNum(v) {
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  if (v.k === 's') return err('#VALUE!')
  return v
}
function fin(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }

function rank(v) { return v.k === 'n' ? 0 : v.k === 's' ? 1 : 2 }
function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (a.k === 's') {
    const x = [...a.v], y = [...b.v]
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  const x = a.k === 'b' ? (a.v ? 1 : 0) : a.v
  const y = b.k === 'b' ? (b.v ? 1 : 0) : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function ev(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'range': return err('#ERR!')
    case 'ref': {
      const a = parseAddr(n.a)
      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'un': {
      const v = ev(n.e)
      if (v.k === 'e') return v
      const x = toNum(v)
      if (x.k === 'e') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = ev(n.l), r = ev(n.r)
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const res = n.op === '=' ? d === 0 : n.op === '<>' ? d !== 0 : n.op === '<' ? d < 0 : n.op === '<=' ? d <= 0 : n.op === '>' ? d > 0 : d >= 0
        return { k: 'b', v: res }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return call(n)
  }
}

const VARIADIC = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
function call(n) {
  const { name, args } = n
  if (VARIADIC.includes(name)) {
    const vals = []
    for (const a of args) {
      if (a.n === 'range') {
        const cs = expandRange(a.a, a.b)
        if (!cs) { vals.push(err('#REF!')); continue }
        for (const c of cs) vals.push(cellValue(c.col, c.row))
      } else vals.push(ev(a))
    }
    const e = vals.find((v) => v.k === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
    const ns = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'e') return x
      ns.push(x.v)
    }
    if (name === 'SUM') return fin(ns.reduce((s, x) => s + x, 0))
    if (name === 'AVG') return fin(ns.reduce((s, x) => s + x, 0) / ns.length)
    if (name === 'MIN') return num(ns.reduce((a, b) => (b < a ? b : a)))
    return num(ns.reduce((a, b) => (b > a ? b : a)))
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const x = toNum(ev(args[0]))
    return x.k === 'e' ? x : num(Math.abs(x.v))
  }
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = ev(args[0])
    if (c.k === 'e') return c
    if (c.k === 's') return err('#VALUE!')
    const t = c.k === 'b' ? c.v : c.v !== 0
    return ev(args[t ? 1 : 2])
  }
  return err('#NAME?')
}

// ---- output
function fmt(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function collect(n, set) {
  switch (n.n) {
    case 'ref': { const a = parseAddr(n.a); if (a) set.set(a.col + a.row, a); break }
    case 'range': { const cs = expandRange(n.a, n.b); if (cs) for (const c of cs) set.set(c.col + c.row, c); break }
    case 'un': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': for (const a of n.args) collect(a, set); break
  }
}

const out = []
for (const cell of sorted) {
  const addr = cell.col + cell.row
  if (mode === 'values') {
    out.push(`${addr}=${fmt(cellValue(cell.col, cell.row))}`)
  } else {
    const set = new Map()
    const ast = cell.content[0] === '=' ? getAst(cell) : null
    if (ast) collect(ast, set)
    const list = [...set.values()].sort((a, b) => colCmp(a.col, b.col) || a.row - b.row)
    out.push(`${addr}:` + list.map((c) => ` ${c.col}${c.row}`).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
